defmodule JoobQ.BatchesTest do
  use ExUnit.Case, async: true

  alias JoobQ.Batches

  test "members and callbacks are jobs, and the batch context is merged under their own" do
    body =
      Batches.body(
        [{"mail", "send", %{"to" => 1}, context: %{"trace" => "mine"}}, {"mail", "send"}],
        description: "newsletter",
        context: %{"tenant" => "t1", "trace" => "batch"},
        on_complete: {"mail", "report", %{}, max_retries: 1}
      )

    assert %{"jobs" => [first, second], "description" => "newsletter", "on_complete" => done} =
             body

    assert first["context"] == %{"tenant" => "t1", "trace" => "mine"}
    assert second["context"] == %{"tenant" => "t1", "trace" => "batch"}
    assert %{"job_type" => "report", "max_retries" => 1, "context" => %{"tenant" => "t1"}} = done
    refute Map.has_key?(body, "on_failure") or Map.has_key?(body, "on_success")
    refute Map.has_key?(Batches.body([{"q", "t"}], []), "description")
  end

  test "a batch id is a UUID, refused before any call otherwise" do
    uuid = "0b9f6f9e-1c2d-4e5f-8a9b-0c1d2e3f4a5b"
    assert Batches.path(uuid) == "/batches/" <> uuid

    for id <- ["..", ".", "", "b-1", uuid <> "/..", String.duplicate("a", 300), nil] do
      assert_raise ArgumentError, ~r/UUID/, fn -> Batches.path(id) end
      assert_raise ArgumentError, ~r/UUID/, fn -> JoobQ.get_batch(id, name: :nowhere) end
    end
  end

  test "what the gateway refuses is refused here, named without its value" do
    for {jobs, opts, wanted} <- [
          {[], [], ~r/1 to 1000/},
          {List.duplicate({"q", "t"}, 1001), [], ~r/1 to 1000/},
          {[{"q", "t", %{}, unique_key: "k"}], [], ~r/:unique_key/},
          {[{"q", "t"}], [on_failure: {"q", "cb", %{}, delay_ms: 5}], ~r/:delay_ms/},
          {[{"q", "t"}], [on_success: {"q", "cb", %{}, encrypt_fields: ["a"]}],
           ~r/:encrypt_fields/},
          {[{"q", "t"}], [context: "hunter2"], ~r/:context/},
          {[{"q", "t"}], [description: String.duplicate("d", 501)], ~r/:description/},
          {[:job], [], ~r/job is/},
          {[{"q", "t"}], [other: 1], ~r/:other/}
        ] do
      error = assert_raise ArgumentError, wanted, fn -> Batches.body(jobs, opts) end
      refute error.message =~ "hunter2"
    end
  end
end
